 await check('all241 embedded presets match the exact final catalog bytes and measurement shot schemas',()=>{const catalogBytes=fs.readFileSync(path.join(root,'SPINDOCTOR_PRESETS.json')),catalog=JSON.parse(catalogBytes),presets=JSON.parse(JSON.stringify(ui.getPresets()));assert.equal(presets.length,241);assert.match(html,new RegExp('"sourceSha256":"'+crypto.createHash('sha256').update(catalogBytes).digest('hex')+'"'));let ordinary=0,collapse=0;for(let i=0;i<241;i++){assert.equal(presets[i].id,catalog.presets[i].id);assert.deepEqual(presets[i].commands,catalog.presets[i].commands);assert.equal(presets[i].description,catalog.presets[i].description);for(const f of presets[i].parameterSchema.filter(f=>f.minimum!=null)){assert.equal(f.type,'integer');assert.equal(f.minimum,1);if(presets[i].id==='qc-015'){assert.equal(f.default,1);assert.equal(f.maximum,1);assert.equal(f.singleCollapse,true);collapse++;}else{assert.equal(f.default,1024);assert.equal(f.maximum,100000);assert.equal(f.singleCollapse,false);ordinary++;}}}assert.equal(ordinary,132);assert.equal(collapse,1);for(const id of ['qc-208','qc-209'])assert.equal(presets.find(p=>p.id===id).parameterSchema.some(f=>f.key==='shots'),false);assert.match(html,/id="measureShots"[^>]*max="100000"[^>]*value="1024"/);});
